        Ok(match (&self.expression.kind, &mut self.position) {
            (
                K::Block { statements, tail }
                | K::VecConstructor {
                    statements, tail, ..
                },
                Position::Block {
                    statement,
                    child: index,
                },
            ) => {
                loop {
                    work(1)?;
                    let Some(item) = statements.get(*statement) else {
                        break;
                    };
                    if *index < item.child_count() {
                        let result = item.child(*index);
                        *index += 1;
                        return Ok(result);
                    }
                    *statement += 1;
                    *index = 0;
                }
                if *index == 0 {
                    *index = 1;
                    Some(tail)
                } else {
                    None
                }
